-- =====================================================================
-- Arkadaş düellosu
-- ---------------------------------------------------------------------
--  * Öğrenci aynı dershaneden bir arkadaşını seçtiği derste düelloya çağırır.
--    Sunucu havuzdan 10 soru seçer; ikisi de aynı soruları çözer.
--  * Sorular "Başla"ya basılınca açılır (start_duel); süre sunucuda ölçülür,
--    doğru sayısı sunucudaki cevap anahtarından (practice_keys) hesaplanır.
--    İstemcinin bildirdiği puana ya da süreye güvenilmez.
--  * Kazanan: daha çok doğru; eşitse testi daha kısa sürede bitiren. Süre de
--    eşitse berabere.
--  * Kazanana avatar ödülü: avatar_items'ta {"type": "duel_wins"} kuralı.
--  * Davet 48 saat geçerli; süresi dolan ve iki taraf bitirmemiş düello
--    sonuçsuz kalır. Başlayan oyuncu 30 dakika içinde bitirmelidir.
--  * Tablolara istemci doğrudan erişemez; her şey fonksiyonlarla.
--
-- Cevap anahtarı assets/learn/questions/*.json ile aynı olmalı:
-- supabase/tests/duels_test.mjs denetler. Havuz yeniden üretilirse bu
-- migration'ın sonundaki practice_keys satırları da yeniden üretilmeli.
--
-- Geri almak için: supabase/rollbacks/20261018230000_duels.down.sql
-- =====================================================================

create table public.practice_keys (
  question_id text primary key check (question_id ~ '^(TYT|AYT)_[A-Z0-9]{3,4}-[0-9]{4}$'),
  answer      smallint not null check (answer between 0 and 4)
);
alter table public.practice_keys enable row level security;
revoke all on public.practice_keys from anon, authenticated;

create table public.duels (
  id                     uuid primary key default gen_random_uuid(),
  tenant_id              uuid not null references public.tenants (id),
  challenger             uuid not null references public.profiles (id) on delete cascade,
  opponent               uuid not null references public.profiles (id) on delete cascade,
  subject_code           text not null,
  question_ids           text[] not null check (cardinality(question_ids) = 10),
  created_at             timestamptz not null default now(),
  expires_at             timestamptz not null default now() + interval '48 hours',
  challenger_started_at  timestamptz,
  challenger_finished_at timestamptz,
  challenger_correct     smallint,
  challenger_ms          int,
  opponent_started_at    timestamptz,
  opponent_finished_at   timestamptz,
  opponent_correct       smallint,
  opponent_ms            int,
  winner                 uuid,
  decided_at             timestamptz,
  check (challenger <> opponent)
);
create index on public.duels (challenger, created_at desc);
create index on public.duels (opponent, created_at desc);
create index on public.duels (tenant_id);
create index on public.duels (winner) where winner is not null;
alter table public.duels enable row level security;
revoke all on public.duels from anon, authenticated;

-- Bildirim türleri
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind in ('assignment', 'exam', 'task', 'note', 'deletion_request',
                  'meeting', 'review', 'weekly_report', 'daily_question',
                  'duel', 'duel_result'));

-- Avatar kuralı: kazanılan düello sayısı
create or replace function public.avatar_rule_met(p_user uuid, p_rule jsonb)
returns boolean
language plpgsql stable security definer set search_path = ''
as $$
begin
  return case p_rule ->> 'type'
    when 'free'   then true
    when 'streak' then public.student_best_streak(p_user) >= coalesce((p_rule ->> 'days')::int, 1)
    when 'net'    then public.student_best_net(p_user, p_rule ->> 'exam_type')
                         >= coalesce((p_rule ->> 'value')::numeric, 0)
    when 'badge'  then public.student_has_badge(p_user, p_rule ->> 'badge')
    when 'questions' then (
      select coalesce(sum(correct + wrong + blank), 0)
      from public.question_logs where student_id = p_user
    ) >= coalesce((p_rule ->> 'count')::int, 1)
    when 'study_minutes' then (
      select coalesce(sum(duration_sec), 0) / 60
      from public.study_sessions where student_id = p_user
    ) >= coalesce((p_rule ->> 'minutes')::int, 1)
    when 'topics' then (
      select count(*) from public.topic_progress
      where student_id = p_user and status = 'done'
    ) >= coalesce((p_rule ->> 'count')::int, 1)
    when 'exams' then (
      select count(*) from public.exams where student_id = p_user
    ) >= coalesce((p_rule ->> 'count')::int, 1)
    when 'duel_wins' then (
      select count(*) from public.duels where winner = p_user
    ) >= coalesce((p_rule ->> 'count')::int, 1)
    else false   -- bilinmeyen kural: güvenli tarafta kal
  end;
end;
$$;
revoke execute on function public.avatar_rule_met(uuid, jsonb) from public, anon, authenticated;

