-- Düelloya çağrılabilecek arkadaşlar: aynı dershanedeki diğer öğrenciler.
create or replace function public.duel_opponents()
returns table (student_id uuid, display_name text, avatar jsonb)
language sql stable security definer set search_path = ''
as $$
  select p.id, public.leaderboard_name(p.full_name), p.avatar
  from public.profiles p
  where public.my_role() = 'student'
    and public.my_tenant_active()
    and p.role = 'student'
    and p.org_id = public.my_org()
    and p.tenant_id = public.my_tenant()
    and p.id <> auth.uid()
  order by p.full_name
$$;
revoke execute on function public.duel_opponents() from public, anon;
grant execute on function public.duel_opponents() to authenticated;

create or replace function public.create_duel(p_opponent uuid, p_subject text)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_me  public.profiles%rowtype;
  v_op  public.profiles%rowtype;
  v_ids text[];
  v_id  uuid;
begin
  select * into v_me from public.profiles where id = auth.uid();
  if not found or v_me.role <> 'student' or not public.my_tenant_active() then
    raise exception 'DUEL_NOT_ALLOWED';
  end if;
  select * into v_op from public.profiles where id = p_opponent;
  if not found or v_op.role <> 'student' or v_op.id = v_me.id
     or v_op.org_id is distinct from v_me.org_id
     or v_op.tenant_id is distinct from v_me.tenant_id then
    raise exception 'DUEL_BAD_OPPONENT';
  end if;
  -- Aynı ikili arasında aynı anda tek açık düello; günde en çok 10 davet.
  if exists (select 1 from public.duels d
             where d.decided_at is null and d.expires_at > now()
               and ((d.challenger = v_me.id and d.opponent = v_op.id)
                 or (d.challenger = v_op.id and d.opponent = v_me.id))) then
    raise exception 'DUEL_ALREADY_OPEN';
  end if;
  if (select count(*) from public.duels
      where challenger = v_me.id and created_at > now() - interval '24 hours') >= 10 then
    raise exception 'DUEL_DAILY_LIMIT';
  end if;

  select array_agg(question_id) into v_ids from (
    select question_id from public.practice_keys
    where split_part(question_id, '-', 1) = p_subject
    order by random() limit 10
  ) q;
  if coalesce(cardinality(v_ids), 0) < 10 then
    raise exception 'DUEL_BAD_SUBJECT';
  end if;

  insert into public.duels (tenant_id, challenger, opponent, subject_code, question_ids)
  values (v_me.tenant_id, v_me.id, v_op.id, p_subject, v_ids)
  returning id into v_id;

  insert into public.notifications (user_id, kind, ref_id, data)
  values (v_op.id, 'duel', v_id, jsonb_build_object(
    'from', public.leaderboard_name(v_me.full_name),
    'subject', p_subject,
    'route', '/student/duels'));
  return v_id;
end;
$$;
revoke execute on function public.create_duel(uuid, text) from public, anon;
grant execute on function public.create_duel(uuid, text) to authenticated;

-- Süreyi başlatır (bir kez) ve soruları verir. Sorular bundan önce görünmez.
create or replace function public.start_duel(p_duel uuid)
returns text[]
language plpgsql security definer set search_path = ''
as $$
declare
  v_me uuid := auth.uid();
  d public.duels%rowtype;
begin
  select * into d from public.duels where id = p_duel for update;
  if not found or v_me not in (d.challenger, d.opponent) then
    raise exception 'DUEL_NOT_FOUND';
  end if;
  if v_me = d.challenger then
    if d.challenger_finished_at is not null then raise exception 'DUEL_ALREADY_FINISHED'; end if;
    if d.challenger_started_at is null then
      if d.expires_at <= now() then raise exception 'DUEL_EXPIRED'; end if;
      update public.duels set challenger_started_at = now() where id = d.id;
    end if;
  else
    if d.opponent_finished_at is not null then raise exception 'DUEL_ALREADY_FINISHED'; end if;
    if d.opponent_started_at is null then
      if d.expires_at <= now() then raise exception 'DUEL_EXPIRED'; end if;
      update public.duels set opponent_started_at = now() where id = d.id;
    end if;
  end if;
  return d.question_ids;
end;
$$;
revoke execute on function public.start_duel(uuid) from public, anon;
grant execute on function public.start_duel(uuid) to authenticated;

-- Cevapları alır (10 şık, boş için -1); doğru sayısını ve süreyi sunucu
-- hesaplar. İki taraf da bitirdiyse kazananı belirler ve iki tarafa sonuç
-- bildirimi gönderir.
create or replace function public.finish_duel(p_duel uuid, p_answers smallint[])
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_me uuid := auth.uid();
  d public.duels%rowtype;
  v_correct int;
  v_ms int;
  v_winner uuid;
  v_names jsonb;
begin
  if coalesce(cardinality(p_answers), 0) <> 10 then
    raise exception 'DUEL_BAD_ANSWERS';
  end if;
  select * into d from public.duels where id = p_duel for update;
  if not found or v_me not in (d.challenger, d.opponent) then
    raise exception 'DUEL_NOT_FOUND';
  end if;

  select count(*) into v_correct
  from unnest(d.question_ids, p_answers) as a(qid, ans)
  join public.practice_keys k on k.question_id = a.qid and k.answer = a.ans;

  if v_me = d.challenger then
    if d.challenger_started_at is null then raise exception 'DUEL_NOT_STARTED'; end if;
    if d.challenger_finished_at is not null then raise exception 'DUEL_ALREADY_FINISHED'; end if;
    if now() > d.challenger_started_at + interval '30 minutes' then raise exception 'DUEL_TIMEOUT'; end if;
    v_ms := (extract(epoch from now() - d.challenger_started_at) * 1000)::int;
    update public.duels set challenger_finished_at = now(), challenger_correct = v_correct,
                            challenger_ms = v_ms
    where id = d.id returning * into d;
  else
    if d.opponent_started_at is null then raise exception 'DUEL_NOT_STARTED'; end if;
    if d.opponent_finished_at is not null then raise exception 'DUEL_ALREADY_FINISHED'; end if;
    if now() > d.opponent_started_at + interval '30 minutes' then raise exception 'DUEL_TIMEOUT'; end if;
    v_ms := (extract(epoch from now() - d.opponent_started_at) * 1000)::int;
    update public.duels set opponent_finished_at = now(), opponent_correct = v_correct,
                            opponent_ms = v_ms
    where id = d.id returning * into d;
  end if;

  if d.challenger_finished_at is not null and d.opponent_finished_at is not null then
    v_winner := case
      when d.challenger_correct > d.opponent_correct then d.challenger
      when d.opponent_correct > d.challenger_correct then d.opponent
      when d.challenger_ms < d.opponent_ms then d.challenger
      when d.opponent_ms < d.challenger_ms then d.opponent
    end;
    update public.duels set winner = v_winner, decided_at = now() where id = d.id;

    -- Ödül parçası, kazanan uygulamayı açınca claim_avatar_unlocks ile açılır
    -- ("yeni parça" bildirimi de böylece çıkar).

    select jsonb_object_agg(id, public.leaderboard_name(full_name)) into v_names
    from public.profiles where id in (d.challenger, d.opponent);
    insert into public.notifications (user_id, kind, ref_id, data)
    select u.me, 'duel_result', d.id, jsonb_build_object(
             'result', case when v_winner is null then 'draw' when v_winner = u.me then 'won' else 'lost' end,
             'opponent', v_names ->> u.other::text,
             'subject', d.subject_code,
             'route', '/student/duels')
    from (values (d.challenger, d.opponent), (d.opponent, d.challenger)) as u(me, other);
  end if;
  return v_winner;
end;
$$;
revoke execute on function public.finish_duel(uuid, smallint[]) from public, anon;
grant execute on function public.finish_duel(uuid, smallint[]) to authenticated;

-- Oturumdaki öğrencinin düelloları. Rakibin sonucu ancak kendin bitirince
-- görünür (önceden görüp ona göre oynamak olmasın).
create or replace function public.my_duels()
returns table (
  id               uuid,
  subject_code     text,
  is_challenger    boolean,
  opponent_name    text,
  opponent_avatar  jsonb,
  created_at       timestamptz,
  expires_at       timestamptz,
  status           text,
  my_correct       int,
  my_ms            int,
  their_finished   boolean,
  their_correct    int,
  their_ms         int,
  result           text
)
language sql stable security definer set search_path = ''
as $$
  with mine as (
    select d.*, (d.challenger = auth.uid()) as ch
    from public.duels d
    where auth.uid() in (d.challenger, d.opponent)
  ), v as (
    select m.*,
           case when ch then m.opponent else m.challenger end as other_id,
           case when ch then m.challenger_started_at else m.opponent_started_at end as my_start,
           case when ch then m.challenger_finished_at else m.opponent_finished_at end as my_end,
           case when ch then m.challenger_correct else m.opponent_correct end as my_c,
           case when ch then m.challenger_ms else m.opponent_ms end as my_t,
           case when ch then m.opponent_started_at else m.challenger_started_at end as their_start,
           case when ch then m.opponent_finished_at else m.challenger_finished_at end as their_end,
           case when ch then m.opponent_correct else m.challenger_correct end as their_c,
           case when ch then m.opponent_ms else m.challenger_ms end as their_t
    from mine m
  )
  select v.id, v.subject_code, v.ch, public.leaderboard_name(p.full_name), p.avatar,
         v.created_at, v.expires_at,
         case
           when v.decided_at is not null then 'done'
           when v.my_end is null and (
             (v.my_start is null and v.expires_at > now())
             or (v.my_start is not null and v.my_start + interval '30 minutes' > now())) then 'your_turn'
           when v.my_end is not null and (
             (v.their_start is null and v.expires_at > now())
             or (v.their_start is not null and v.their_start + interval '30 minutes' > now())) then 'waiting'
           else 'expired'
         end,
         v.my_c, v.my_t,
         v.their_end is not null,
         case when v.my_end is not null then v.their_c end,
         case when v.my_end is not null then v.their_t end,
         case when v.decided_at is null then null
              when v.winner is null then 'draw'
              when v.winner = auth.uid() then 'won' else 'lost' end
  from v
  join public.profiles p on p.id = v.other_id
  order by v.created_at desc
  limit 50
$$;
revoke execute on function public.my_duels() from public, anon;
grant execute on function public.my_duels() to authenticated;

